Record rindex := RI { ri_vars : list (list kentry); ri_other : list kentry }.
Definition ri_bucket (ri : rindex) (k : option nat) : list kentry := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S0;Lri;Ri69;Lk;RA1;i70;i41;m70;RNLk;RA1;i70;i41;A1;i60;i71;r1;2;Ln;Ri41;A3;k68;i71;A1;k72;r3;r1;A1;k73;r2;").
Fixpoint mk_ri (fk : list kentry) : rindex :=
  match fk with
  | [] => RI [] []
  | K :: rest =>
      let t := mk_ri rest in
      match K with
      | KRange e' _ _ =>
          match vkey_of e' with
          | Some n => RI (lset (ri_vars t) n K) (ri_other t)
          | None => RI (ri_vars t) (K :: ri_other t)
          end
      | _ => t
      end
  end.
Definition find_rangeI (ri : rindex) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S0;Lri;Ri69;Le;Ri32;A2;k74;A2;k75;r2;A1;k76;r1;r1;").

