Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S16;A2;i91;i35;i35;A1;i70;#0;Px;Ri32;#1;A2;i91;i35;i32;A1;i60;#3;A3;o65;#3;r3;r2;A1;r11;r3;A2;k119;r11;r5;A2;k119;r11;r4;m91;RNLp0;RA2;i91;i35;i35;#1;r1;1;Llo;Ri35;Lhi;Ri35;m2;RNL~Ri2;#1;A2;k100;o101;r11;2;A2;o79;#0;A4;o99;i35;i35;A2;k105;r2;#7;A2;k105;r1;#8;A2;o79;#0;A4;o99;i35;i35;A2;k105;r2;#8;A2;k105;r1;#7;A1;o86;#0;A1;r12;r4;m70;RNLx;RA1;i70;#0;#1;#11;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;#1;r1;1;Lal;Ri35;Lah;Ri35;m70;RNLx;RA1;i70;#0;#1;A3;k118;r15;r14;r6;2;Lp0;R#0;#9;#10;#10;A2;k119;r10;r5;A2;k119;r10;r4;A3;o65;#3;A4;o99;i35;i32;r4;r3;r2;Lr1;R#2;Lr2;R#2;Lc;Ri35;Lts;R#4;LH;RPa;Ri32;A3;i1;#1;A1;r5;r1;A1;r4;r1;A5;k90;#3;Lts;R#4;A3;i1;#1;A3;k118;r6;r4;r1;A3;k118;r5;r4;r1;A2;o6;#1;A3;k118;r4;r3;A1;o62;#3;La0;R#3;m91;RNLp;RA2;i91;i35;i32;Pl;R#4;P~RA3;i1;#1;A3;k118;r8;r6;r1;A3;k118;r7;r6;r1;A3;i1;#1;A3;k118;r9;r7;#5;A3;k118;r8;r7;#5;r1;1;Lz;Ri35;Le;Ri32;A2;Lk;Ri35;La;Ri32;Lrest;R#4;LIH;RA3;i1;#1;A3;k118;r11;r9;r1;A3;k118;r10;r9;r1;cdA6;k40;#1;#6;Lo;R#1;A3;i1;#1;m70;RNLx;RA1;i70;#0;#1;r1;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;#1;r1;1;Lal;Ri35;Lah;Ri35;m70;RNLx;RA1;i70;#0;#1;A3;k118;r16;r14;r6;2;Lp0;R#0;#9;#10;#10;#12;A6;k40;#1;A3;k118;r11;r10;r2;Lo;R#1;A3;i1;#1;m70;RNLx;RA1;i70;#0;#1;#11;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;#1;r1;1;Lal;Ri35;Lah;Ri35;m70;RNLx;RA1;i70;#0;#1;r4;2;Lp0;R#0;#9;#10;#10;#12;A2;o6;#1;m70;RNLx;RA1;i70;#0;#1;#6;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;#1;r1;1;Lal;Ri35;Lah;Ri35;m70;RNLx;RA1;i70;#0;#1;A3;k118;r14;r13;r5;2;Lp0;R#0;m91;RNLp0;RA2;i91;i35;i35;#1;r1;1;Llo;Ri35;Lhi;Ri35;m2;RNL~Ri2;#1;A2;k100;o101;r10;2;A2;o79;#0;A4;o99;i35;i35;A2;k105;r2;#13;A2;k105;r1;#14;A2;o79;#0;A4;o99;i35;i35;A2;k105;r2;#14;A2;k105;r1;#13;#10;#10;A3;k118;r12;r10;r2;r1;A1;r12;r3;A1;r8;r3;A3;i1;#1;A3;k118;r12;r10;#15;A3;k118;r11;r10;#15;r2;r1;r2;").
Qed.
End FPX_1.

Ltac beq_crush rw :=
  repeat (first [ reflexivity
                | progress rw
                | lazymatch goal with
                  | |- ?L = _ =>
                      lazymatch L with
                      | (if ?c then _ else _) => destruct c
                      | (match ?x with _ => _ end) => destruct x
                      end
                  end ]).
Section FPX_2. Context {fx : PropExec.FPState}.

Fixpoint erange_fB (fuel : nat) (bc : bctx) (e : expr) {struct fuel} : option (Z * Z) :=
  match fuel with
  | O => None
  | S fuel' =>
  let erange := erange_fB fuel' in
  match find_rangeI (bc_ri bc) e with
  | Some r => Some (clampi r)
  | None =>
  match (let l := lin_of e in
         if lin_trivial l then None
         else match lin_range (erange bc) (fst l) (snd l) with
              | Some (lo, hi) =>

                  let q := zdiv64 lo in
                  if Z.eqb q (zdiv64 hi) then Some ((lo - q * two64)%Z, (hi - q * two64)%Z) else None
              | None => None
              end) with
  | Some r => Some r
  | None =>
  match e with
  | ELit z => let v := zmod64 z in Some (v, v)
  | EVar _ => None
  | EAlu op a b =>
      match op with
      | ALU_ADD =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if Z.ltb (ah + bh) two64 then Some ((al + bl)%Z, (ah + bh)%Z)
              else if Z.leb two64 (al + bl) then Some ((al + bl - two64)%Z, (ah + bh - two64)%Z)
              else None
          | _, _ => None
          end
      | ALU_SUB =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if Z.leb bh al then Some ((al - bh)%Z, (ah - bl)%Z)
              else if Z.ltb ah bl then Some ((al - bh + two64)%Z, (ah - bl + two64)%Z)
              else None
          | _, _ => None
          end
      | ALU_AND =>

          match (match b, erange bc a with
                 | ELit m, Some (al, ah) =>
                     let m' := (m mod two64)%Z in
                     let j := Z.log2 (m' + 1) in
                     if (Z.eqb (m' + 1) (2 ^ j) && Z.leb (al / 2 ^ j) (ah / 2 ^ j) && Z.eqb (al / 2 ^ j) (ah / 2 ^ j))%bool
                     then Some ((al mod 2 ^ j)%Z, (ah mod 2 ^ j)%Z)
                     else let jh := Z.log2 (two64 - m') in
                          if (Z.eqb (two64 - m') (2 ^ jh) && Z.ltb jh 64)%bool
                          then Some ((al - al mod 2 ^ jh)%Z, (ah - ah mod 2 ^ jh)%Z)
                          else None
                 | _, _ => None
                 end) with
          | Some r => Some r
          | None =>
          match erange bc a, erange bc b with
          | Some (_, ah), Some (_, bh) => Some (0%Z, Z.min ah bh)
          | Some (_, ah), None => Some (0%Z, ah)
          | None, Some (_, bh) => Some (0%Z, bh)
          | None, None => None
          end
          end
      | ALU_OR =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) => Some (Z.max al bl, mask_cover (Z.max ah bh))
          | _, _ => None
          end
      | ALU_XOR =>
          match erange bc a, erange bc b with
          | Some (_, ah), Some (_, bh) => Some (0%Z, mask_cover (Z.max ah bh))
          | _, _ => None
          end
      | ALU_SRL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s => Some ((al / 2 ^ s)%Z, (ah / 2 ^ s)%Z)
          | _, _ => None
          end
      | ALU_SRA =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              if Z.ltb ah (2 ^ 63) then Some ((al / 2 ^ s)%Z, (ah / 2 ^ s)%Z) else None
          | _, _ => None
          end
      | ALU_SLL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              if Z.ltb (ah * 2 ^ s) two64 then Some ((al * 2 ^ s)%Z, (ah * 2 ^ s)%Z) else None
          | _, _ => None
          end
      | ALU_SLTU =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if Z.ltb ah bl then Some (1%Z, 1%Z)
              else if Z.leb bh al then Some (0%Z, 0%Z) else Some (0%Z, 1%Z)
          | _, _ => Some (0%Z, 1%Z)
          end
      | ALU_SLT =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.ltb ah (2 ^ 63) && Z.ltb bh (2 ^ 63))%bool then
                (if Z.ltb ah bl then Some (1%Z, 1%Z)
                 else if Z.leb bh al then Some (0%Z, 0%Z) else Some (0%Z, 1%Z))
              else Some (0%Z, 1%Z)
          | _, _ => Some (0%Z, 1%Z)
          end
      end
  | EAluw op a b =>
      match op with
      | ALU_ADD =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              let bl' := if Z.eqb bl bh then zsigned64 bl else bl in
              let bh' := if Z.eqb bl bh then zsigned64 bh else bh in
              if (Z.leb 0 (al + bl') && Z.ltb (ah + bh') (2 ^ 31))%bool
              then Some ((al + bl')%Z, (ah + bh')%Z) else None
          | _, _ => None
          end
      | ALU_SUB =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.leb bh al && Z.ltb (ah - bl) (2 ^ 31))%bool
              then Some ((al - bh)%Z, (ah - bl)%Z) else None
          | _, _ => None
          end
      | ALU_SLL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              let s' := (s mod 32)%Z in
              if Z.ltb (ah * 2 ^ s') (2 ^ 31) then Some ((al * 2 ^ s')%Z, (ah * 2 ^ s')%Z) else None
          | _, _ => None
          end
      | ALU_SRL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              let s' := (s mod 32)%Z in
              if (Z.ltb ah (2 ^ 32) && (Z.ltb 0 s' || Z.ltb ah (2 ^ 31)))%bool
              then Some ((al / 2 ^ s')%Z, (ah / 2 ^ s')%Z) else None
          | _, _ => None
          end
      | ALU_SRA =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              let s' := (s mod 32)%Z in
              if Z.ltb ah (2 ^ 31) then Some ((al / 2 ^ s')%Z, (ah / 2 ^ s')%Z) else None
          | _, _ => None
          end
      | _ => None
      end
  | EMd op a b =>
      match op with
      | M_MUL =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.leb 0 al && Z.leb 0 bl && Z.ltb (ah * bh) two64)%bool
              then Some ((al * bl)%Z, (ah * bh)%Z) else None
          | _, _ => None
          end
      | M_MULHU =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.leb 0 al && Z.leb 0 bl)%bool
              then Some ((al * bl / two64)%Z, (ah * bh / two64)%Z) else None
          | _, _ => None
          end
      | M_DIVU =>
          match erange bc a, b with
          | Some (al, ah), ELit d =>
              let d' := (d mod two64)%Z in
              if Z.ltb 0 d' then Some ((al / d')%Z, (ah / d')%Z) else None
          | _, _ => None
          end
      | M_REMU =>
          match erange bc a, b with
          | Some (al, ah), ELit d =>
              let d' := (d mod two64)%Z in
              if Z.ltb 0 d' then Some (0%Z, Z.min ah (d' - 1)) else None
          | _, _ => None
          end
      | _ => None
      end
  | EMdw _ _ _ => None
  | EExt sx lo n a =>
      let w := (2 ^ (8 * Z.of_nat n))%Z in
      if sx then
        match lo, erange bc a with
        | O, Some (al, ah) =>
            if (Z.leb 0 al && Z.ltb ah (w / 2))%bool then Some (al, ah)
            else if (Nat.leb 1 n && Nat.leb n 8 && Z.leb (w / 2) al && Z.ltb ah w)%bool
                 then Some ((two64 - w + al)%Z, (two64 - w + ah)%Z) else None
        | _, _ => None
        end
      else
        match lo, erange bc a with
        | O, Some (al, ah) =>
            if (Z.leb 0 al && Z.ltb ah w)%bool then Some (al, ah) else Some (0%Z, Z.min (w - 1) (two64 - 1))
        | _, _ => Some (0%Z, Z.min (w - 1) (two64 - 1))
        end
  | EBlob sx k i n =>

      if sx then Some (0%Z, two64m1) else Some (0%Z, Z.min (2 ^ (8 * Z.of_nat n) - 1) (two64 - 1))%Z
  end
  end
  end
  end.

Definition erange0B (bc : bctx) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_k (rplG ()) 2 "U0;Lbc;Ri120;Le;Ri32;A3;k121;k122;r2;r1;").

Definition erangeB (bc : bctx) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S2;A2;i91;i35;i35;A1;i70;#0;Lbc;Ri120;Le;Ri32;Er;RA2;k123;r2;r1;#1;m91;RNLx;RA2;i91;i32;i35;#1;A1;k124;r2;1;Le';Ri32;Ls;Ri35;m2;RNL~Ri2;#1;A2;k37;r1;o101;2;r3;m70;RNLx;RA1;i70;#0;#1;A2;k123;r5;A1;k125;A1;k126;r2;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;#1;r1;1;Llo';Ri35;Lhi';Ri35;m2;RNL~Ri2;#1;A2;k100;r4;r2;2;m70;RNLr;RA1;i70;#0;#1;r6;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;#1;r1;1;Llo;Ri35;Lhi;Ri35;A2;o79;#0;A4;o99;i35;i35;A2;k127;r2;A2;k106;r5;r7;A2;k128;r1;r4;A2;o79;#0;A4;o99;i35;i35;A2;k106;r2;r4;r1;r6;r3;").

Definition base_rangeB (bc : bctx) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S3;A2;i91;i35;i35;A2;k131;r5;r4;A2;k131;r6;r5;Lbc;Ri120;Le;Ri32;m32;RNLe;Ri32;A1;i70;#0;r1;8;Lz;Ri35;Ev;RA2;k129;r1;k130;i35;A2;o79;#0;A4;o99;i35;i35;r1;r1;Ln;Ri41;A2;k131;r3;r2;Lop;Ri0;La;Ri32;Lb;Ri32;#1;Lop;Ri0;La;Ri32;Lb;Ri32;#1;Lop;Ri22;La;Ri32;Lb;Ri32;#1;Lop;Ri22;La;Ri32;Lb;Ri32;#1;Lsx;Ri2;Llo;Ri41;Ln;Ri41;Le0;Ri32;#2;Lsx;Ri2;Lk;Ri41;Li;Ri35;Ln;Ri41;#2;").

Definition ealignB (bc : bctx) (e : expr) : Z := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S0;Lbc;Ri120;Le;Ri32;A2;k127;A2;k132;A1;k133;r2;r1;A1;k134;r1;").

Definition lin_nowrapB (bc : bctx) (e : expr) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S1;A1;i60;A2;i91;i35;i32;Lbc;Ri120;Le;Ri32;El;RA1;k126;r1;k135;m70;RNLx;RA1;i70;A2;i91;i35;i35;i2;A3;k118;A1;k131;r3;A3;k58;i35;#0;r1;A3;k136;i35;#0;r1;2;Lp;RA2;i91;i35;i35;m91;RNLp;RA2;i91;i35;i35;i2;r1;1;Llo;Ri35;Lhi;Ri35;A2;k51;A2;k100;o101;r2;A2;k102;r1;k130;o7;").

Fixpoint srl_expandB (bc : bctx) (ts : list (Z * expr)) : Z * list (Z * expr) :=
  match ts with
  | [] => (0%Z, [])
  | (k, a) :: rest =>
      let '(c, ts') := srl_expandB bc rest in
      let keep := (c, lins_e k a ts') in
      match a with
      | EAlu ALU_SRL e (ELit s) =>
          let m := (2 ^ ((s mod two64) mod 64))%Z in
          if (Z.eqb (k mod m)%Z 0%Z && lin_nowrapB bc e)%bool then
            let q := (k / m)%Z in
            let le := lin_of e in
            if Z.leb ((s mod two64) mod 64) (ealignB bc e) then
              ((c + q * fst le)%Z, fold_right (fun t acc => lins_e (q * fst t)%Z (snd t) acc) ts' (snd le))
            else
            ((c + q * fst le)%Z,
             lins_e (- q)%Z (srl_rem e m) (fold_right (fun t acc => lins_e (q * fst t)%Z (snd t) acc) ts' (snd le)))
          else keep
      | EAlu ALU_AND e (ELit mk) =>

          match highmask_s mk with
          | Some s =>
              if lin_nowrapB bc e then
                let le := lin_of e in
                ((c + k * fst le)%Z,
                 lins_e (- k)%Z (srl_rem e (2 ^ s)) (fold_right (fun t acc => lins_e (k * fst t)%Z (snd t) acc) ts' (snd le)))
              else keep
          | None => keep
          end
      | _ => keep
      end
  end.

Definition fact_nowrapB (bc : bctx) (e : expr) (hi : Z) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S1;A1;i60;A2;i91;i35;i32;Lbc;Ri120;Le;Ri32;Lhi;Ri35;El;RA1;k126;r2;k135;m70;RNLx;RA1;i70;A2;i91;i35;i35;i2;A3;k118;A1;k131;r4;A3;k58;i35;#0;r1;A3;k136;i35;#0;r1;2;Lp;RA2;i91;i35;i35;m91;RNLp;RA2;i91;i35;i35;i2;r1;1;La;Ri35;Lb;Ri35;A2;k51;A2;k102;r1;k130;A2;k102;r5;A2;k105;r2;k130;o7;").

Definition sum_fact_xB (bc : bctx) (ts : list (Z * expr)) (lo hi : Z) : list sfact := ltac2:(Rpl.RP.run_k (rplG ()) 4 "S6;A2;i91;i35;i32;A1;i60;#0;A1;i60;k115;A1;o62;k115;A2;i91;i35;i35;A2;i91;#1;#4;Lbc;Ri120;Lts;R#1;Llo;Ri35;Lhi;Ri35;m91;RNLx;RA2;i91;i35;#1;#2;A2;k137;r4;r3;1;Lc2;Ri35;Lts2;R#1;m60;RNLts2;RA1;i60;#0;#2;r1;2;#3;Lp;R#0;Ll;RA1;i60;#0;m2;RNL~Ri2;#2;A2;k37;r4;o101;2;#3;A3;o65;#5;A4;o99;#1;#4;r3;A4;o99;i35;i35;A2;k106;r6;r4;A2;k106;r5;r4;A1;o62;#5;").

Fixpoint sum_factsB (bc : bctx) (kn : list kentry) : list sfact :=
  match kn with
  | [] => []
  | KRange e lo hi :: rest =>
      match e with
      | EVar _ => sum_factsB bc rest
      | _ =>
        match lin_of e with
        | (c, (_ :: _ :: _) as ts) =>
            if fact_nowrapB bc e hi then (ts, ((lo - c)%Z, (hi - c)%Z)) :: sum_fact_xB bc ts (lo - c)%Z (hi - c)%Z ++ sum_factsB bc rest
            else sum_factsB bc rest
        | _ => sum_factsB bc rest
        end
      end
  | _ :: rest => sum_factsB bc rest
  end.

Lemma bc_fk_mkbc0 : forall fk fs, bc_fk (mkbc0 fk fs) = fk. Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S1;A1;i60;i71;Lfk;R#0;Lfs;RA1;i60;k115;A2;o6;#0;r2;").
Qed.
Lemma bc_ffk_mkbc0 : forall fk fs, bc_ffk (mkbc0 fk fs) = facts_of fk. Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S1;A1;i60;i71;Lfk;R#0;Lfs;RA1;i60;k115;A2;o6;#0;A1;k117;r2;").
Qed.
Lemma find_rangeI_mkbc0 : forall fk fs, find_rangeI (bc_ri (mkbc0 fk fs)) = find_range (facts_of fk).
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S0;Lfk;RA1;i60;i71;Lfs;RA1;i60;k115;A5;k138;i32;A1;i70;A2;i91;i35;i35;A1;k139;A1;k140;A2;k141;r2;r1;A1;k74;A1;k117;r2;Le;Ri32;A2;k142;A1;k117;r3;r1;").
Qed.
End FPX_2.

