#[export] Hint Rewrite ranges_apart_pB_eqf : bceq.
Section FPX_52. Context {fx : PropExec.FPState}.

Fixpoint coeffs_divkB (bc : bctx) (m : Z) (ts : list (Z * expr)) : bool :=
  match ts with
  | [] => true
  | (k, a) :: rest => ((Z.eqb (k mod m) 0 || Z.eqb ((k * 2 ^ ealignB bc a) mod m) 0) && coeffs_divkB bc m rest)%bool
  end.

Definition lin_lowbits_knB (bc : bctx) (e : expr) (k : Z) : option Z := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S2;A2;k103;A1;o104;Y1;0;r2;A1;i60;A2;i91;i35;i32;Lbc;Ri120;Le;Ri32;Lk;Ri35;El;RA1;k126;r2;k135;m2;RNL~Ri2;A1;i70;i35;A3;k331;r4;#0;A3;k136;i35;#1;r1;2;A2;o79;i35;A2;k129;A3;k58;i35;#1;r1;#0;A2;k332;r3;#0;").

