Definition mkSrlB (bc : bctx) (a : expr) (s : Z) : expr := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S9;A1;k233;A1;k146;r2;A2;i91;i35;i32;A1;i60;#1;A3;k136;i35;#2;r2;A2;k172;r5;r4;A1;o62;#1;A2;i91;i35;i35;A3;k58;i35;#2;r8;A2;k152;r2;r10;Lbc;Ri120;La;Ri32;Ls;Ri35;El;RA1;k126;r2;k135;Em;RA2;k103;A1;o104;Y1;0;r2;i35;m2;RNL~Ri2;i32;A2;k51;A2;k51;#0;A2;k333;r1;#3;#4;2;A1;k125;A4;o99;i35;#2;A2;k152;A3;k58;i35;#2;r2;r1;A2;k334;r1;#3;m91;RNLx;RA2;i91;#2;#2;i32;m2;RNL~Ri2;A2;i91;#2;#2;A2;k51;#0;#4;2;A2;k335;r1;#3;A4;o99;#2;#2;#5;#5;1;Ldts;R#2;Lrts;R#2;m60;RNLdts;RA1;i60;#1;i32;r2;2;A3;k229;o18;r6;A1;o36;r5;Lp;R#1;Ll0;RA1;i60;#1;m60;RNLrts;RA1;i60;#1;i32;r3;2;A3;k229;o18;r8;A1;o36;r7;Lp0;R#1;Ll1;RA1;i60;#1;m70;RNLx;RA1;i70;#6;i32;m2;RNL~Ri2;A1;i70;#6;A3;k336;r11;#7;r5;2;A2;k163;r11;A1;k125;A4;o99;i35;#2;#7;r5;A1;o86;#6;2;Lp;R#6;m91;RNLp;RA2;i91;i35;i35;i32;r1;1;Llo;Ri35;Lhi;Ri35;m2;RNL~Ri2;i32;A2;k37;#8;A2;k152;r1;r10;2;A1;k125;A4;o99;i35;#2;#8;A2;k334;r10;r9;A3;k229;o18;r13;A1;o36;r12;A3;k229;o18;r10;A1;o36;r9;").

Fixpoint lowbitsB (bc : bctx) (e : expr) (j : Z) {struct e} : option Z :=
  let m := (2 ^ j)%Z in
  let dflt := if Z.leb j (ealignB bc e) then Some 0%Z else lin_lowbits_knB bc e j in
  match e with
  | ELit z => Some ((z mod two64) mod m)%Z
  | EAlu ALU_AND a (ELit c) =>
      if Z.eqb ((c mod two64) mod m) 0 then Some 0%Z else
      match lowbitsB bc a j with Some v => Some (Z.land v ((c mod two64) mod m)) | None => dflt end
  | EAlu ALU_OR a (ELit c) =>
      match lowbitsB bc a j with Some v => Some (Z.lor v ((c mod two64) mod m)) | None => dflt end
  | EAlu ALU_XOR a (ELit c) =>
      match lowbitsB bc a j with Some v => Some (Z.lxor v ((c mod two64) mod m)) | None => dflt end
  | EAlu ALU_ADD a b =>
      match lowbitsB bc a j, lowbitsB bc b j with Some x, Some y => Some ((x + y) mod m)%Z | _, _ => dflt end
  | EAlu ALU_SUB a b =>
      match lowbitsB bc a j, lowbitsB bc b j with Some x, Some y => Some ((x - y) mod m)%Z | _, _ => dflt end
  | EMd M_MUL (ELit c) a =>
      if Z.eqb ((c mod two64) mod m) 0 then Some 0%Z else
      match lowbitsB bc a j with Some v => Some ((c * v) mod m)%Z | None => dflt end
  | _ => dflt
  end.

Fixpoint lsplit_divB (bc : bctx) (m : Z) (ts : list (Z * expr)) : list (Z * expr) * list (Z * expr) :=
  match ts with
  | [] => ([], [])
  | (k, a) :: rest =>
      let (d, r) := lsplit_divB bc m rest in
      if (Z.eqb (k mod m) 0 || Z.eqb ((k * 2 ^ ealignB bc a) mod m) 0)%bool then ((k, a) :: d, r) else (d, (k, a) :: r)
  end.

