Fixpoint tagged (kn : list kentry) (i : positive) : list (positive * kentry) :=
  match kn with [] => [] | K :: rest => (i, K) :: tagged rest (Pos.succ i) end.
Definition all_gt (i : positive) (l : list (positive * kentry)) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S1;A2;i91;i470;i71;Li;Ri470;Ll;RA1;i60;#0;A3;i579;#0;Lt;R#0;A2;k580;r3;A3;k58;i470;i71;r1;r1;").

