Fixpoint scan_entries (bc : bctx) (kn : list kentry) (t : ntab) (gs : gst) : list (option einfo) * ntab * gst :=
  match kn with
  | [] => ([], t, gs)
  | K :: rest =>
      match kdescr K with
      | Some (kb, kk, om) =>
          let '(r, t1) := intern bc t kb in
          let '(bid, bi) := r in
          let '(gid, gs1) := match om with
                             | Some m => let '(gid, gs0) := ggroup gs bid kk in (gid, bnd_add gs0 gid bid (bi_br bi) kk (kk + m)%Z)
                             | None => (xH, gs)
                             end in
          let '(infos, t2, gs2) := scan_entries bc rest t1 gs1 in
          (Some (EI bid gid kb (bi_br bi) kk om) :: infos, t2, gs2)
      | None =>
          let '(infos, t2, gs2) := scan_entries bc rest t gs in
          (None :: infos, t2, gs2)
      end
  end.

Definition sx_m1 (sx : stx) : Z := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S0;Lsx;Ri934;A1;k210;A1;k156;A1;k937;r1;").

Definition verdict (sx : stx) (g : gval) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S3;A2;i91;i35;i35;A1;i70;#0;A1;k224;A1;k936;r14;Lsx;Ri934;Lg;Rk999;m91;RNLg;RA2;i91;A2;i91;i470;#1;#0;i2;r1;1;Lp;RA2;i91;i470;#1;Lp0;R#0;m91;RNLp;RA2;i91;i470;#1;i2;r2;1;Lb;Ri470;Lobr;R#1;m91;RNLp0;RA2;i91;i35;i35;i2;r3;1;Lglo;Ri35;Lghi;Ri35;m2;RNL~Ri2;i2;A2;k932;r4;A1;k961;r8;2;o7;m70;RNLx;RA1;i70;#0;i2;A1;k238;A1;k935;r8;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;i2;r1;1;Llo1;Ri35;Lhi1;Ri35;m70;RNLobr;RA1;i70;#0;i2;r6;2;Lp0;R#0;m91;RNLp0;RA2;i91;i35;i35;i2;r1;1;Llo2;Ri35;Lhi2;Ri35;A2;k155;A2;k100;A2;k106;A2;k105;A2;k105;r4;#2;A1;k1007;r14;r2;r8;A2;k100;r7;A2;k106;A2;k105;r5;#2;r1;o7;o7;").

Fixpoint mk_fl (g : gval) (sxs : list stx) : list (stx * list stx) :=
  match sxs with
  | [] => []
  | sx :: rest => if verdict sx g then mk_fl g rest else (sx, rest) :: mk_fl g rest
  end.
